snippets.catalogue_filter:
use ngano::{Catalogue, Filter};

/// Datasets for the language tag {{LANGUAGE}}, read from the snapshot built
/// into the crate. This function never touches the network.
///
/// A language is a BCP 47 tag whose primary subtag is an ISO 639-3 code, so
/// sna is Shona and eng-NG is Nigerian English. A name such as "isiZulu"
/// works too, and resolves to its tag.
pub fn ngano_catalogue() -> Result<(), ngano::NganoError> {
    let cat = Catalogue::bundled()?;

    let hits = cat.datasets(
        &Filter::new()
            .language("{{LANGUAGE}}")
            .task("{{TASK}}")
            .commercial(true),
    );

    for d in &hits {
        println!("{} ({}, {})", d.name, d.licence, d.access);
    }

    let stats = cat.stats_for(hits);
    println!("{} datasets, {:.0} counted hours", stats.datasets, stats.hours);
    Ok(())
}

snippets.stream_filter:
use futures::TryStreamExt;
use ngano::{Filter, Loader};

/// Stream rows for the language tag {{LANGUAGE}}, one page at a time, and
/// read the audio lazily.
pub async fn ngano_stream() -> Result<(), ngano::NganoError> {
    let mut stream = Loader::new()
        .filter(Filter::new().language("{{LANGUAGE}}").commercial(true))
        .split("train")
        .hf_token(std::env::var("HF_TOKEN").ok())
        .limit(Some(1000))
        .stream()
        .await?;

    while let Some(row) = stream.try_next().await? {
        println!("{:?}", row.transcript.as_deref());

        if let Some(audio) = &row.audio {
            let bytes = audio.read().await?;
            println!("{} bytes", bytes.len());
        }
    }
    Ok(())
}

snippets.single_dataset:
use futures::TryStreamExt;
use ngano::Loader;

/// Stream the {{CONFIG}} config of {{HF_REPO}} directly, whether or not the
/// catalogue lists that repo.
pub async fn ngano_repo() -> Result<(), ngano::NganoError> {
    let mut stream = Loader::new()
        .repo("{{HF_REPO}}")
        .config("{{CONFIG}}")
        .split("train")
        .hf_token(std::env::var("HF_TOKEN").ok())
        .limit(Some(100))
        .stream()
        .await?;

    while let Some(row) = stream.try_next().await? {
        println!(
            "{:?} {:?}",
            row.language_tag.as_deref(),
            row.transcript.as_deref()
        );
    }
    Ok(())
}

snippets.language_page:
use futures::TryStreamExt;
use ngano::{Catalogue, Filter, Loader};

/// What ngano holds for the language tag {{LANGUAGE}}: the catalogue first,
/// then the rows.
pub async fn ngano_language() -> Result<(), ngano::NganoError> {
    let cat = Catalogue::bundled()?;
    let filter = Filter::new().language("{{LANGUAGE}}");

    // A bare code such as eng covers the language at large. Add
    // .include_varieties(true) to take in eng-NG, eng-ZA and the rest.

    let stats = cat.stats_for(cat.datasets(&filter));
    println!(
        "{{LANGUAGE}}: {} datasets, {:.0} counted hours",
        stats.datasets, stats.hours
    );

    let mut stream = Loader::new()
        .catalogue(cat)
        .filter(filter)
        .split("train")
        .limit(Some(500))
        .stream()
        .await?;

    while let Some(row) = stream.try_next().await? {
        println!("{:?}", row.transcript.as_deref());
    }
    Ok(())
}

snippets.country_page:
use futures::TryStreamExt;
use ngano::{Catalogue, Filter, Loader};

/// Speech data recorded in {{COUNTRY_NAME}}, selected by its ISO code.
pub async fn ngano_country() -> Result<(), ngano::NganoError> {
    let cat = Catalogue::bundled()?;
    let filter = Filter::new().country("{{COUNTRY_ISO2}}").hf_only(true);

    println!("{{COUNTRY_NAME}}");
    for d in cat.datasets(&filter) {
        println!("  {} ({})", d.name, d.languages_clean.join(", "));
    }

    let mut stream = Loader::new()
        .catalogue(cat)
        .filter(filter)
        .limit(Some(200))
        .stream()
        .await?;

    while let Some(row) = stream.try_next().await? {
        println!("{:?}", row.transcript.as_deref());
    }
    Ok(())
}

snippets.dataset_page:
use futures::TryStreamExt;
use ngano::{Catalogue, Loader};

/// The catalogue record for {{DATASET_ID}}, then its rows.
pub async fn ngano_dataset() -> Result<(), ngano::NganoError> {
    let cat = Catalogue::bundled()?;

    let d = cat.require("{{DATASET_ID}}")?;
    println!("{} ({}, {})", d.name, d.licence, d.access);
    println!("{}", d.notes);

    let mut stream = Loader::new()
        .catalogue(cat.clone())
        .dataset("{{DATASET_ID}}")
        .split("train")
        .hf_token(std::env::var("HF_TOKEN").ok())
        .limit(Some(100))
        .stream()
        .await?;

    while let Some(row) = stream.try_next().await? {
        println!("{:?}", row.transcript.as_deref());
    }
    Ok(())
}
